/* ---------------- unit 8: Vilse i fjällen (sammansatta ord) ---------------- */
W("fjall",{sv:"fjäll (ett)",m:rx("fjäll(et|en|ens)?"),d:t3("Ett högt berg i norra Sverige, ofta utan träd på toppen.","A high mountain in northern Sweden, often with no trees on top.","جبل عالٍ في شمال السويد، غالبًا بلا أشجار في قمّته."),ex:"Klassen åkte till fjällen.",tr:{en:"mountain, fell",ar:"جبل"},syn:["berg"],opp:["dal"],wrong:["sjö","skog"],gap:["Vi vandrade upp på","fjället","och tittade ut."],gapForm:"fjället",form:"ett fjäll – fjäll"});
W("stuga",{sv:"stuga (en)",m:rx("stug(a|an|or|orna)"),d:t3("Ett litet hus, ofta på landet eller i fjällen.","A small house, often in the countryside or mountains.","بيت صغير، غالبًا في الريف أو في الجبال."),ex:"Stugan låg vid en sjö.",tr:{en:"cabin, cottage",ar:"كوخ"},syn:["litet hus"],wrong:["skola","affär"],gap:["Klassen bodde i en","stuga","vid en sjö."],gapForm:"stuga",form:"en stuga – stugor"});
W("utsikt",{sv:"utsikt (en)",m:rx("utsikt(en|er)?"),d:t3("Det man ser när man tittar ut, långt bort.","What you see when you look out, far away.","ما تراه عندما تنظر إلى البعيد."),ex:"Från toppen var utsikten fantastisk.",tr:{en:"view",ar:"منظر"},syn:["vy"],wrong:["väg","karta"],gap:["Från fönstret hade vi en fin","utsikt","över bergen."],gapForm:"utsikt",form:"en utsikt – utsikter"});
W("packning",{sv:"packning (en)",m:rx("packning(en|ar)?"),d:t3("Det man har packat med sig, till exempel i en ryggsäck.","What you have packed, for example in a backpack.","ما حزمته معك، مثلًا في حقيبة الظهر."),ex:"Lena kontrollerade allas packning.",tr:{en:"gear, luggage",ar:"الأمتعة"},syn:["bagage"],wrong:["mat","karta"],gap:["Har du regnjackan i din","packning","?"],gapForm:"packning",form:"en packning – packningar"});
W("dimma",{sv:"dimma (en)",m:rx("dimm(a|an|or)"),d:t3("Moln nära marken, så att man inte ser långt.","Cloud near the ground, so you can't see far.","سحاب قريب من الأرض فلا ترى بعيدًا."),ex:"En grå dimma kom rullande.",tr:{en:"fog, mist",ar:"ضباب"},syn:["tjocka"],wrong:["regn","vind"],gap:["Vi såg bara några meter framåt i","dimman","."],gapForm:"dimman",form:"en dimma – dimmor"});
W("vilse",{sv:"gå vilse",m:rx("vilse"),d:t3("Inte hitta vägen och inte veta var man är.","Not find the way and not know where you are.","ألّا تجد الطريق ولا تعرف أين أنت."),ex:"Vi har gått vilse!",tr:{en:"get lost",ar:"يضلّ الطريق"},syn:["komma bort"],opp:["hitta rätt"],wrong:["somna","springa"],gap:["Utan karta är det lätt att gå","vilse","i skogen."],gapForm:"vilse",form:"gå vilse – gick vilse – har gått vilse"});
W("kompass",{sv:"kompass (en)",m:rx("kompass(en|er)?"),d:t3("Ett verktyg med en nål som alltid pekar mot norr.","A tool with a needle that always points north.","أداة لها إبرة تشير دائمًا إلى الشمال."),ex:"Sara tog fram en kompass.",tr:{en:"compass",ar:"بوصلة"},wrong:["klocka","karta"],gap:["Nålen på en","kompass","pekar mot norr."],gapForm:"kompass",form:"en kompass – kompasser"});
W("modig",{sv:"modig",m:rx("modig(t|a|are)?"),d:t3("Som vågar göra något fast det är farligt eller svårt.","Daring to do something even if it is dangerous or hard.","من يجرؤ على فعل شيء رغم خطورته أو صعوبته."),ex:"Ni var modiga.",tr:{en:"brave",ar:"شجاع"},syn:["djärv","tapper"],opp:["feg","rädd"],wrong:["trött","arg"],gap:["Det var","modigt","att gå först i mörkret."],gapForm:"modigt",form:"modig – modigt – modiga"});
W("sammansattord",{sv:"sammansatt ord",m:rx("sammansatt(a)? ord(et|en)?"),d:t3("Ett ord som är byggt av två eller fler ord.","A word built from two or more words.","كلمة مبنيّة من كلمتين أو أكثر."),ex:"fjäll + stuga = fjällstuga",tr:{en:"compound word",ar:"كلمة مركّبة"}});
W("forled",{sv:"förled",m:rx("förled(et|en)?"),d:t3("Första delen i ett sammansatt ord.","The first part of a compound word.","الجزء الأول من الكلمة المركّبة."),ex:"fjäll i fjällstuga",tr:{en:"first part (of a compound)",ar:"الجزء الأول"}});
W("efterled",{sv:"efterled",m:rx("efterled(et|en)?"),d:t3("Sista delen i ett sammansatt ord. Den säger vad det är.","The last part of a compound word. It says what the thing is.","الجزء الأخير من الكلمة المركّبة، وهو يحدّد ما هو الشيء."),ex:"stuga i fjällstuga",tr:{en:"last part, head word",ar:"الجزء الأخير"}});
W("fogs",{sv:"fog-s",m:rx("fog-s"),d:t3("Ett s som ibland binder ihop orden i ett sammansatt ord.","An s that sometimes joins the parts of a compound word.","حرف s يربط أحيانًا بين جزأي الكلمة المركّبة."),ex:"fotboll + s + lag = fotbollslag",tr:{en:"linking s",ar:"حرف s الرابط"}});
